/*
 * declared.h -- Entry points a DLL exports so that a program's imports
 * resolve, without behaviour behind them yet.
 *
 * Each one is generated by dlls/declared.py from the DLL's declared.txt. When
 * called, it reports itself once on the debug output, sets the last error to
 * ERROR_CALL_NOT_IMPLEMENTED (stdcall functions only: the C runtime has no
 * last error), and returns the value its table gives, popping its arguments
 * as the real function would. See docs/userland/WIN32.md.
 */
#ifndef SAVANXP_WIN32_DECLARED_H
#define SAVANXP_WIN32_DECLARED_H

typedef struct sxw_declared {
    unsigned seen;    /* set on the first call */
    unsigned stdcall; /* nonzero: set the last error */
    const char *name; /* "dll!Function" */
} sxw_declared;

/* Called by every generated entry point with its record. */
void __cdecl sxw_declared_hit(sxw_declared *record);

#endif
